import{_ as t}from"./chunks/Reptor_Bike.DnvosJou.js";import{_ as a}from"./chunks/Bildlogo_SysLeaks.B5zaKZH-.js";import{_ as s,o as r,c as i,ap as o}from"./chunks/framework.CuFS6FqL.js";const y=JSON.parse('{"title":"What we provide","description":"Overview of Syslifters offensive security services, our efficient pentesting approach, and services we do not offer.","frontmatter":{"title":"What we provide","description":"Overview of Syslifters offensive security services, our efficient pentesting approach, and services we do not offer."},"headers":[],"relativePath":"what-we-provide.md","filePath":"what-we-provide.md"}'),n={name:"what-we-provide.md"};function c(d,e,l,p,h,u){return r(),i("div",null,[...e[0]||(e[0]=[o('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /what-we-provide.md for this page in Markdown format</div><h1 id="what-we-provide" tabindex="-1">What we provide <a class="header-anchor" href="#what-we-provide" aria-label="Permalink to &quot;What we provide&quot;">​</a></h1><p>We provide offensive security services to customers in the DACH region and beyond. Our specialisations are internal enterprise networks (Active Directory, Entra ID and Azure cloud), external infrastructure and web security. With this clear focus we help you find and fix real risks.</p><p>We work efficiently (and keep your costs down) with a grey-to-white-box approach, a clear time box, and, where it makes sense, agreed leg-ups such as an assumed-breach starting point instead of lengthy and costly covert end-to-end campaigns.</p><h2 id="services-we-offer" tabindex="-1">Services we offer <a class="header-anchor" href="#services-we-offer" aria-label="Permalink to &quot;Services we offer&quot;">​</a></h2><ul><li><a href="#assumed-breach-assessments">Assumed breach assessments</a></li><li><a href="#active-directory-pentests">Active Directory pentests</a></li><li><a href="#entra-id-and-azure-cloud-assessments">Entra ID and Azure cloud assessments</a></li><li><a href="#external-infrastructure-pentests">External infrastructure pentests</a></li><li><a href="#web-application-pentests">Web application pentests</a></li><li><a href="#attack-detection-response-tests">Attack detection &amp; response tests</a></li><li><a href="#password-analysis">Password analysis</a></li><li><a href="#load-tests">Load tests</a></li></ul><h3 id="assumed-breach-assessments" tabindex="-1">Assumed breach assessments <a class="header-anchor" href="#assumed-breach-assessments" aria-label="Permalink to &quot;Assumed breach assessments&quot;">​</a></h3><p>Tests from a starting point where an attacker might already be inside, for example a standard domain user, a compromised workstation, or an agreed internal foothold. The initial compromise phase is out of scope. From there we work towards the goals agreed for the scope, for example reaching domain admin, accessing a defined target system, or exfiltrating specific data. On request we can align techniques with known threat actor TTPs.</p><h3 id="active-directory-pentests" tabindex="-1">Active Directory pentests <a class="header-anchor" href="#active-directory-pentests" aria-label="Permalink to &quot;Active Directory pentests&quot;">​</a></h3><p>Pentests of on-prem and hybrid Active Directory environments. We look at the attack paths and misconfigurations that ransomware actors and attackers with an existing foothold (for example a compromised workstation or device) typically exploit. The outcome is a clear picture of how an attack would propagate from a single endpoint to your most sensitive systems.</p><h3 id="entra-id-and-azure-cloud-assessments" tabindex="-1">Entra ID and Azure cloud assessments <a class="header-anchor" href="#entra-id-and-azure-cloud-assessments" aria-label="Permalink to &quot;Entra ID and Azure cloud assessments&quot;">​</a></h3><p>Identity and configuration review of Microsoft Entra ID and Azure, including hybrid scenarios where Entra ID and on-prem AD intersect. We assess identity risk, access policies and the attack paths between cloud and on-premises identities that real attackers use to move laterally and escalate privileges. The result shows how a compromised cloud account could affect your on-prem environment, and the other way around.</p><h3 id="external-infrastructure-pentests" tabindex="-1">External infrastructure pentests <a class="header-anchor" href="#external-infrastructure-pentests" aria-label="Permalink to &quot;External infrastructure pentests&quot;">​</a></h3><p>Pentests of your external attack surface: exposed services, patching gaps, misconfigurations and paths into your environment. Often combined with Active Directory or Entra ID work for a full external-to-internal picture, so you see not only what is reachable from the internet but also where it leads inside.</p><h3 id="web-application-pentests" tabindex="-1">Web application pentests <a class="header-anchor" href="#web-application-pentests" aria-label="Permalink to &quot;Web application pentests&quot;">​</a></h3><p>Manual pentests of web applications and APIs, following common best practices such as the OWASP Testing Guide. We test at least grey-box with authenticated access and can extend to white-box with source code review when useful. Coverage focuses on findings that affect your specific risk model, including business logic, authentication and authorization, data handling and relevant integrations.</p><h3 id="attack-detection-response-tests" tabindex="-1">Attack detection &amp; response tests <a class="header-anchor" href="#attack-detection-response-tests" aria-label="Permalink to &quot;Attack detection &amp; response tests&quot;">​</a></h3><p>Realistic attack techniques executed in your environment, so you can evaluate whether your SOC, SIEM and response processes detect and handle them. We coordinate closely with your blue team and report on which techniques were noticed, which were missed, and where detection rules could be tuned. The result is concrete, technique-level feedback for your detection engineering.</p><h3 id="password-analysis" tabindex="-1">Password analysis <a class="header-anchor" href="#password-analysis" aria-label="Permalink to &quot;Password analysis&quot;">​</a></h3><p>Analysis of password hygiene, for example in Active Directory: weak passwords, common patterns, reuse and policy gaps. A focused, low-effort way to surface accounts and policies that need attention. Useful before or alongside a pentest, since weak credentials are still one of the most common starting points for real attacks.</p><h3 id="load-tests" tabindex="-1">Load tests <a class="header-anchor" href="#load-tests" aria-label="Permalink to &quot;Load tests&quot;">​</a></h3><p>Performance and stability tests of web applications under load, scoped separately from vulnerability testing and agreed in advance to avoid unintended impact. We help you understand how your application behaves under realistic and peak load, and where bottlenecks, errors or stability issues appear. A useful complement to security testing for applications that have to survive real user traffic.</p><h2 id="what-we-don-t-provide" tabindex="-1">What we don&#39;t provide <a class="header-anchor" href="#what-we-don-t-provide" aria-label="Permalink to &quot;What we don&#39;t provide&quot;">​</a></h2><p>We are experts in offensive security. Having the best knowledge in a domain makes focus mandatory.</p><p>This is why we don&#39;t provide:</p><ul><li>SOC/SIEM services</li><li>Incident response</li><li>ISMS consulting</li><li>CISO as a service</li><li>Awareness trainings</li></ul><p>For services outside our scope we can recommend partners. We do not take referral fees.</p><h2 id="further-projects" tabindex="-1">Further projects <a class="header-anchor" href="#further-projects" aria-label="Permalink to &quot;Further projects&quot;">​</a></h2><p>Two products grew out of our daily pentest work and are run as separate services: SysReptor, our pentest reporting platform, and SysLeaks, our data leak monitoring service.</p><div style="display:flex;justify-content:center;flex-wrap:wrap;"><a href="https://docs.sysreptor.com" target="_blank" style="display:flex;justify-content:center;"><figure style="width:15em;margin:0.5em;"><img alt="SysReptor Pentest Reporting" src="'+t+'"><figcaption>SysReptor Pentest Reporting</figcaption></figure></a><a href="https://sysleaks.com" target="_blank" style="display:flex;justify-content:center;"><figure style="width:15em;margin:0.5em;"><img alt="SysLeaks" src="'+a+'"><figcaption>SysLeaks Data Leak Monitoring</figcaption></figure></a></div>',30)])])}const v=s(n,[["render",c]]);export{y as __pageData,v as default};
